const D = params.diameter;
const R = D * 0.5;
const n = params.gondolas;
const hubY = R + D * 0.18;
const frameZ = D * 0.16;
const rimTube = D * 0.018;
const primary = { preset: 'metal', color: params.color, metalness: 0.55, roughness: 0.3 };
const dark = { preset: 'metal', color: '#26323b', metalness: 0.75, roughness: 0.25 };
const trim = { preset: 'metal', color: '#e6c75a', metalness: 0.65, roughness: 0.28 };
const glass = { preset: 'glass', color: '#8ed7e8', roughness: 0.08, opacity: 0.72 };
const light = { preset: 'emissive', color: '#fff2ad', emissive: '#ffd86b', emissiveIntensity: 3.2, roughness: 0.2 };
const groundY = D * 0.025;
api.add(api.box(D * 0.92, D * 0.05, D * 0.46).translate(0, groundY, 0), { preset: 'concrete', color: '#777d80', roughness: 0.9 });
api.add(api.box(D * 0.98, D * 0.025, D * 0.52).translate(0, D * 0.0125, 0), { preset: 'stone', color: '#4e5559', roughness: 0.85 });
for (let side = -1; side <= 1; side += 2) {
  const z = side * frameZ;
  api.add(api.tube([[-R * 0.68, D * 0.05, z], [0, hubY, z], [R * 0.68, D * 0.05, z]], D * 0.035, 8), primary);
  api.add(api.tube([[-R * 0.52, D * 0.34, z], [R * 0.52, D * 0.34, z]], D * 0.022, 8), primary);
  api.add(api.box(D * 0.22, D * 0.07, D * 0.1).translate(-R * 0.68, D * 0.075, z), dark);
  api.add(api.box(D * 0.22, D * 0.07, D * 0.1).translate(R * 0.68, D * 0.075, z), dark);
}
api.add(api.cylinder(D * 0.075, D * 0.075, D * 0.46, 16).rotate(90, 0, 0).translate(0, hubY, 0), dark);
api.add(api.cylinder(D * 0.13, D * 0.13, D * 0.055, 16).rotate(90, 0, 0).translate(0, hubY, frameZ + D * 0.035), trim);
api.add(api.cylinder(D * 0.13, D * 0.13, D * 0.055, 16).rotate(90, 0, 0).translate(0, hubY, -frameZ - D * 0.035), trim);
api.add(api.torus(R, rimTube).translate(0, hubY, 0), primary);
api.add(api.torus(R * 0.94, rimTube * 0.7).translate(0, hubY, 0), trim);
const spokeCount = Math.max(12, n * 2);
for (let i = 0; i < spokeCount; i++) {
  const a = i * Math.PI * 2 / spokeCount;
  const x = Math.cos(a) * R * 0.94;
  const y = hubY + Math.sin(a) * R * 0.94;
  api.add(api.tube([[0, hubY, 0], [x, y, 0]], D * 0.008, 6), i % 2 === 0 ? primary : trim);
}
const palette = ['#ef5350', '#f4b942', '#36a2ae', '#5470c6', '#8d63b8', '#54a96b', '#e56b9f', '#f07a3f'];
for (let i = 0; i < n; i++) {
  const a = i * Math.PI * 2 / n;
  const x = Math.cos(a) * R;
  const mountY = hubY + Math.sin(a) * R;
  const cabinW = D * 0.12;
  const cabinH = D * 0.105;
  const cabinD = D * 0.115;
  const barLen = D * 0.105;
  const cabinY = mountY - barLen - cabinH * 0.5;
  const cabinColor = palette[i % palette.length];
  const cabinMat = { preset: 'metal', color: cabinColor, metalness: 0.35, roughness: 0.38 };
  api.add(api.cylinder(D * 0.025, D * 0.025, D * 0.26, 8).rotate(90, 0, 0).translate(x, mountY, 0), dark);
  api.add(api.tube([[x, mountY, -cabinD * 0.42], [x, cabinY + cabinH * 0.42, -cabinD * 0.42]], D * 0.01, 6), dark);
  api.add(api.tube([[x, mountY, cabinD * 0.42], [x, cabinY + cabinH * 0.42, cabinD * 0.42]], D * 0.01, 6), dark);
  api.add(api.box(cabinW, cabinH * 0.62, cabinD).translate(x, cabinY - cabinH * 0.08, 0), cabinMat);
  api.add(api.box(cabinW * 1.08, cabinH * 0.12, cabinD * 1.08).translate(x, cabinY + cabinH * 0.29, 0), trim);
  api.add(api.box(cabinW * 0.72, cabinH * 0.34, D * 0.006).translate(x, cabinY + cabinH * 0.02, cabinD * 0.505), glass);
  api.add(api.box(cabinW * 0.72, cabinH * 0.34, D * 0.006).translate(x, cabinY + cabinH * 0.02, -cabinD * 0.505), glass);
}
const lightCount = Math.max(24, n * 3);
for (let i = 0; i < lightCount; i++) {
  const a = i * Math.PI * 2 / lightCount;
  const x = Math.cos(a) * R;
  const y = hubY + Math.sin(a) * R;
  api.add(api.sphere(D * 0.014, 0).translate(x, y, rimTube * 1.35), light);
  api.add(api.sphere(D * 0.014, 0).translate(x, y, -rimTube * 1.35), light);
}
api.collider({ kind: 'box', halfExtents: [D * 0.49, D * 0.025, D * 0.26], offset: [0, D * 0.025, 0] });
api.collider({ kind: 'box', halfExtents: [D * 0.38, hubY * 0.48, D * 0.04], offset: [0, hubY * 0.48, frameZ], rotation: [0, 0, 0] });
api.collider({ kind: 'box', halfExtents: [D * 0.38, hubY * 0.48, D * 0.04], offset: [0, hubY * 0.48, -frameZ], rotation: [0, 0, 0] });
return api.build();
